function copy(text,sub){let title=text,detail=sub,kind='document';if(/검색|조건|일치하는/.test(text)){title='검색 결과가 없습니다';detail=detail||'검색어나 선택한 조건을 바꿔 주세요.';kind='search'}else if(/수업 기록/.test(text)){title='아직 공개된 수업 기록이 없습니다';detail=detail||'공개된 수업 기록이 이곳에 모입니다.';kind='calendar'}else if(/강좌|수강/.test(text)){title=text.replace(/\.$/,'');detail=detail||'선택한 학생과 조회 조건을 확인해 주세요.';kind='calendar'}else if(/메시지|대화/.test(text)){title=text.replace(/\.$/,'');detail=detail||'메시지를 이곳에서 확인할 수 있습니다.';kind='chat'}else if(/보충|일정|예약/.test(text)){title=text.replace(/\.$/,'');detail=detail||'일정과 선택한 조회 조건을 확인해 주세요.';kind='calendar'}else if(/영상/.test(text)){title=text.replace(/\.$/,'');detail=detail||'공개된 영상을 이곳에서 확인할 수 있습니다.';kind='video'}else if(/알림/.test(text)){title='새로운 알림이 없습니다';detail=detail||'도착한 알림을 이곳에서 확인할 수 있습니다.';kind='chat'}else if(/없습니다|없어요|비어/.test(text)){title=text.replace(/등록된 |표시할 /,'').replace(/\.$/,'');detail=detail||'새로운 내용이 등록되면 이곳에 표시됩니다.'}return{title,detail,kind}}
