 const u=cfg.user?.(),g=generation;if(!u||['parent','student'].includes(u.role))throw Error('강사 또는 관리자 로그인이 필요합니다.');if(state!=='connected'){if(!await connect(!mobile))throw Error(mobile?(detail||'내 PC 연결을 확인해 주세요.'):'PC 연결을 먼저 완료해 주세요.')}
 if(g!==generation||cfg.user?.()?.id!==u.id||payload._site_owner&&payload._site_owner!==u.id)throw Error('사이트 계정이 변경되어 작업을 중단했습니다.');
 if(kind.endsWith('.roster')){const caps=await rpc('check');if(!caps.roster_progress)throw Error('명단 연결 업데이트가 필요합니다. 관리자에게 문의해 주세요.')}
 if(kind==='mswitch.attendance'){const caps=await rpc('check');if(!caps.attendance_v1)throw Error('출결 연결 업데이트가 필요합니다. 관리자에게 문의해 주세요.')}
