const kakaoTasks=new Map();
function kakaoSupported(){return !mobile&&/Win/i.test(navigator.userAgentData?.platform||navigator.platform||navigator.userAgent)}
async function kakaoRPC(action,peer,id,session){
 const c=window.MIRAE_CONFIG||{},p=pairing(),key=c.SUPABASE_KEY,headers={apikey:key,'Content-Type':'application/json'};if(key?.startsWith('eyJ'))headers.Authorization='Bearer '+key;
 let r,d;try{r=await fetch(c.SUPABASE_URL.replace(/\/$/,'')+'/rest/v1/rpc/mirae_kakao_friend',{method:'POST',headers,credentials:'omit',signal:AbortSignal.timeout(10000),body:JSON.stringify({p_session:session,p_device:p.id,p_key:p.key,p_action:action,p_data:{id,peer_id:peer,site_url:siteURL()}})});d=await r.json()}catch{const e=Error('PC의 신호 전송 기록을 받지 못했습니다. 다시 누르면 전송 기록만 확인합니다.');e.uncertain=true;throw e}
 if(!r.ok){const message=String(d.message||''),known={KAKAO_STAFF_REQUIRED:'임직원만 사용할 수 있습니다.',KAKAO_LOCAL_PC_REQUIRED:'현재 PC에서 사이트에 다시 로그인하고 PC 연결을 확인해 주세요.',PC_NOT_PAIRED:'이 PC의 연결 프로그램을 먼저 설치해 주세요.',KAKAO_PHONE_REQUIRED:'상대 직원이 메신저 프로필에 휴대폰 번호를 저장해야 합니다.',KAKAO_NAME_INVALID:'직원 이름을 확인해 주세요.',KAKAO_PEER_INVALID:'사용 중인 다른 직원 계정만 추가할 수 있습니다.',PC_UPDATE_REQUIRED:'PC 연결기 2.9.0 이상으로 업데이트해 주세요.',PC_OFFLINE:'현재 PC 연결기를 실행하고 다시 눌러 주세요.',KAKAO_QUEUE_FULL:'카톡 친추 요청이 많습니다. 앞선 친추가 끝난 뒤 눌러 주세요.',JOB_NOT_FOUND:'이 요청은 처리되지 않았습니다. 다시 눌러 주세요.',KAKAO_REQUEST_INVALID:'요청 정보를 확인할 수 없습니다. 사이트에 다시 로그인해 주세요.'};const found=Object.entries(known).find(([k])=>message.includes(k));const e=Error(['PGRST202','42P01','42883'].includes(d.code)?'카톡 친추 병렬 처리용 SQL 29를 먼저 적용해 주세요.':found?.[1]||'로그인과 PC 연결 상태를 확인해 주세요.');e.code=found?.[0]||d.code;e.uncertain=r.status>=500;throw e}return d;
}
function addKakaoFriend(peerId,onProgress){
 const owner=cfg.user?.()?.id,key=owner+':'+peerId;if(kakaoTasks.has(key))return kakaoTasks.get(key);
 const task=(async()=>{
  if(!kakaoSupported())throw Error('카톡 친추는 Windows PC에서만 사용할 수 있습니다.');
  const u=cfg.user?.(),g=generation;if(!u||!['admin','teacher'].includes(u.role))throw Error('임직원 로그인이 필요합니다.');
  if(state!=='connected'&&!await connect(true))throw Error('현재 PC 연결을 먼저 완료해 주세요.');
  const capabilities=await rpc('check');if(capabilities.kakao_parallel!==true)throw Error('카톡 친추 병렬 처리용 SQL 29를 먼저 적용해 주세요.');
  await bindMobile();if(g!==generation||cfg.user?.()?.id!==owner)throw Error('사이트 계정이 변경되었습니다.');
  const session=(await window.MiraePush.ensureSession()).session,storageKey='mirae-kakao-request:'+pairing().id+':'+key;
  if(g!==generation||cfg.user?.()?.id!==owner)throw Error('사이트 계정이 변경되었습니다.');
  let saved=null;try{saved=JSON.parse(sessionStorage.getItem(storageKey)||'null')}catch{}
  if(saved&&(!/^[a-f0-9-]{36}$/i.test(saved.id||'')||Date.now()-saved.time>7*86400000))saved=null;
  const id=saved?.id||crypto.randomUUID();let d;
  if(!saved){try{sessionStorage.setItem(storageKey,JSON.stringify({id,time:Date.now()}))}catch{};onProgress?.('카카오톡에서 친구 추가 창을 여는 중…');try{d=await kakaoRPC('submit',peerId,id,session)}catch(e){if(!e.uncertain)try{sessionStorage.removeItem(storageKey)}catch{};throw e}}
  const end=Date.now()+50000;
  while(Date.now()<end){
   if(g!==generation||cfg.user?.()?.id!==owner)throw Error('사이트 계정이 변경되었습니다.');
   if(d&&['done','failed','unknown'].includes(d.state)){
    const result=d.result||{};
    if(d.state==='done'||d.state==='failed'){try{sessionStorage.removeItem(storageKey)}catch{}}
    return {...result,ok:d.state==='done'&&result.ok===true,delivered:d.state==='done'&&result.ok===true,state:d.state,message:d.state==='done'&&result.ok===true?'카카오톡으로 친구 추가 신호를 보냈습니다.':result.message||(d.state==='unknown'?'카카오톡 친구 목록을 확인하세요. 결과를 확인하지 못했습니다.':'카카오톡 요청을 처리하지 못했습니다. 다시 눌러 주세요.')};
   }
   onProgress?.(d?.state==='running'?'카카오톡으로 친구 추가 신호를 보내는 중…':'PC에 친구 추가 요청을 전달하는 중…');
   await sleep(1000);
   try{d=await kakaoRPC('status',peerId,id,session)}catch(e){if(e.code==='JOB_NOT_FOUND'){try{sessionStorage.removeItem(storageKey)}catch{};throw e}if(!e.uncertain)throw e;}
  }
  const e=Error('PC의 신호 전송 기록이 아직 도착하지 않았습니다. 다시 누르면 추가 실행 없이 기록만 확인합니다.');e.uncertain=true;throw e;
 })();kakaoTasks.set(key,task);task.finally(()=>{if(kakaoTasks.get(key)===task)kakaoTasks.delete(key)}).catch(()=>{});return task;
}
