const paths={back:'m15 18-6-6 6-6',staff:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M20 21v-2a4 4 0 0 0-3-3.87M16 3a4 4 0 0 1 0 8',chat:'M21 11a8 8 0 0 1-8 8H5l-3 3V11a9 9 0 0 1 19 0ZM7 10h10M7 14h6',search:'m21 21-5-5M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16',phone:'M22 16.9V20a2 2 0 0 1-2.2 2A19.8 19.8 0 0 1 3 5.2 2 2 0 0 1 5 3h3.1a2 2 0 0 1 2 1.7l.5 2.7a2 2 0 0 1-.6 1.7l-1.3 1.3a16 16 0 0 0 5.9 5.9l1.3-1.3a2 2 0 0 1 1.7-.6l2.7.5a2 2 0 0 1 1.7 2Z',send:'m12 19 0-14m-6 6 6-6 6 6',close:'m6 6 12 12M6 18 18 6',down:'m6 9 6 6 6-6',group:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M19 7v6M16 10h6',edit:'m15 4 5 5M3 21l5-1L21 7l-5-5L3 15v6',copy:'M9 9h12v12H9ZM15 9V3H3v12h6'};
