const day=d=>new Date(d).toLocaleDateString('sv-SE',{timeZone:'Asia/Seoul'}),clock=d=>new Date(d).toLocaleTimeString('ko-KR',{timeZone:'Asia/Seoul',hour:'2-digit',minute:'2-digit'});
