const listTime=d=>!d?'':day(d)===day(Date.now())?clock(d):day(d)===day(Date.now()-86400000)?'어제':new Date(d).toLocaleDateString('ko-KR',{timeZone:'Asia/Seoul',month:'numeric',day:'numeric'});
