node.innerHTML='<section class="mc-app" data-screen="list" aria-label="직원 메신저"><header class="mc-mobile-header"><button class="mc-icon" data-mc-exit aria-label="메신저 닫기">'+icon('back')+'</button><h1 data-mc-mobile-title>대화</h1><button class="mc-icon" data-mc-group-new aria-label="단체 대화 만들기">'+icon('group')+'</button><button class="mc-icon" data-mc-me aria-label="내 연락처 설정">'+icon('edit')+'</button></header><aside class="mc-directory"><nav class="mc-tabs" aria-label="메신저 메뉴"><button data-mc-tab="staff">'+icon('staff')+'<span>직원</span></button><button class="active" data-mc-tab="chats">'+icon('chat')+'<span>대화</span><b data-mc-unread hidden></b></button></nav><header class="mc-directory-heading"><div><h2 data-mc-title>대화</h2><small data-mc-list-count></small></div><div class="mc-directory-actions"><button class="mc-icon" data-mc-group-new aria-label="단체 대화 만들기">'+icon('group')+'</button><button class="mc-icon" data-mc-new aria-label="직원 찾아 대화하기">'+icon('edit')+'</button></div></header><label class="mc-list-search">'+icon('search')+'<input data-mc-list-query type="search" placeholder="이름 · 대화 검색" aria-label="직원 및 대화 검색" autocomplete="off"><span class="mc-connection" data-mc-connection role="status"><i></i>연결중</span></label>'+(admin?'<div class="mc-archive"><button class="active" data-mc-scope="own">내 대화</button><button data-mc-scope="all">전체 대화</button></div>':'')+'<button class="mc-my-profile" data-mc-profile-me></button><div class="mc-list" data-mc-list></div><p class="mc-list-status" data-mc-list-status role="status"></p></aside><section class="mc-chat" aria-label="대화창"><div class="mc-welcome" data-mc-welcome>'+MiraeStates.art('chat')+'<h2>대화 상대를 선택해 주세요</h2><p>직원 목록에서 동료를 선택하거나<br>최근 대화를 이어갈 수 있습니다.</p><button class="mc-button" data-mc-welcome-staff>직원 찾아보기</button></div><div class="mc-conversation" hidden><header class="mc-chat-header"><button class="mc-icon mc-chat-back" data-mc-back aria-label="대화 목록으로">'+icon('back')+'</button><button class="mc-peer" data-mc-peer></button><div class="mc-chat-actions"><a class="mc-icon" data-mc-call aria-label="전화하기" hidden>'+icon('phone')+'</a><button class="mc-icon" data-mc-search-toggle aria-label="대화 내용 검색">'+icon('search')+'</button></div></header><form class="mc-chat-search" hidden><input type="search" class="input" name="query" placeholder="이 대화에서 찾기" aria-label="대화 내용 검색"><button class="mc-icon" type="button" data-mc-search-close aria-label="검색 닫기">'+icon('close')+'</button></form><div class="mc-messages" data-mc-messages tabindex="0" aria-label="메시지 목록"></div><button class="mc-new-messages" hidden data-mc-jump>'+icon('down')+'<span>새 메시지</span></button><p class="mc-chat-status" data-mc-status role="status"></p><form class="mc-compose" hidden><div class="mc-input" contenteditable="true" role="textbox" aria-multiline="true" aria-label="메시지 입력" data-placeholder="메시지 입력" inputmode="text" enterkeyhint="send" spellcheck="false" data-mc-input></div><small data-mc-length hidden></small><button class="mc-send" aria-label="메시지 보내기" disabled>'+icon('send')+'</button></form></div></section></section>';
const $=s=>node.querySelector(s),app=$('.mc-app'),list=$('[data-mc-list]'),body=$('[data-mc-messages]'),input=$('[data-mc-input]'),form=$('.mc-compose'),searchForm=$('.mc-chat-search');
function state(t=current){if(!t)return null;if(!stores.has(t.id))stores.set(t.id,{rows:[],cursor:0,lastRead:0,reading:false,hasOlder:false,read:0,readMarkers:[],searchRows:[],searchOlder:false});return stores.get(t.id)}
function mine(t=current){return t&&(t.participant===true||t.members?.some(m=>m.id===uid)||[t.a_id,t.b_id].includes(uid))}
function roomName(t=current){return t?.kind==='group'?t.title:archive&&!mine(t)?t.a_name+' · '+t.b_name:t?.peer_name||'직원'}
function roomAvatar(t){return t.kind==='group'?'<span class="mc-avatar mc-group-avatar" aria-hidden="true">'+icon('staff')+'</span>':avatar(roomName(t),t.id)}
function peerID(t=current){return t?(t.a_id===uid?t.b_id:t.a_id):''}
function peer(t=current){return staff.find(s=>s.id===peerID(t))||{id:peerID(t),name:t?.peer_name||'직원'};}
function connection(ok){if(!valid())return;const b=$('[data-mc-connection]');b.classList.toggle('offline',!ok);b.innerHTML='<i></i>'+(ok?'연결됨':'연결을 기다리는 중');}
function drawList(){if(!valid())return;const q=$('[data-mc-list-query]').value.trim().toLowerCase();const n=cache.rows.reduce((v,t)=>v+Number(t.unread||0),0);$('[data-mc-unread]').hidden=!n;$('[data-mc-unread]').textContent=n>99?'99+':n;$('[data-mc-title]').textContent=tab==='staff'?'직원':'대화';$('[data-mc-mobile-title]').textContent=tab==='staff'?'직원':'대화';$('.mc-archive')?.toggleAttribute('hidden',tab!=='chats');$('[data-mc-profile-me]').hidden=tab!=='staff';
const self=staff.find(s=>s.id===uid)||user;$('[data-mc-profile-me]').innerHTML=avatar(self.name,uid)+'<span><strong>'+esc(self.name)+'</strong><small>내 연락처 설정</small></span>'+icon('edit');
let html;if(tab==='staff'){const rows=staff.filter(s=>s.id!==uid&&[s.name,s.subject,s.phone].join(' ').toLowerCase().includes(q));$('[data-mc-list-count]').textContent=rows.length+'명';html=rows.map(s=>'<button class="mc-row" data-mc-staff="'+esc(s.id)+'">'+avatar(s.name,s.id)+'<span class="mc-row-text"><strong>'+esc(s.name)+'</strong><small>'+esc(s.subject)+(s.role==='admin'?' · 최고관리자':'')+'</small></span><span class="mc-row-arrow">›</span></button>').join('')||'<div class="mc-empty">'+icon('staff')+'<p>일치하는 직원이 없습니다.</p></div>';}else{const rows=threads.filter(t=>[t.peer_name,t.a_name,t.b_name,t.preview].join(' ').toLowerCase().includes(q));$('[data-mc-list-count]').textContent=rows.length+'개';html=rows.map(t=>{const name=roomName(t);return'<div class="mc-row mc-thread '+(current?.id===t.id?'selected':'')+'" data-mc-thread="'+esc(t.id)+'" role="button" tabindex="0">'+(t.kind==='group'?roomAvatar(t):'<button type="button" class="mc-list-avatar" data-mc-list-person="'+esc(peerID(t))+'" aria-label="'+esc(name)+' 프로필">'+roomAvatar(t)+'</button>')+'<span class="mc-row-text"><strong>'+esc(name)+(t.kind==='group'?'<em class="mc-room-count">'+t.members.length+'</em>':'')+'</strong><small>'+(t.last_sender_id===uid?'나: ':'')+esc(t.preview||'아직 대화가 없습니다.')+'</small></span><span class="mc-row-meta"><time>'+esc(listTime(t.last_message_at))+'</time>'+(t.unread&&!archive?'<b>'+Math.min(99,t.unread)+'</b>':'')+'</span></div>'}).join('')||'<div class="mc-empty">'+icon('chat')+'<h3>'+(q?'검색 결과가 없습니다.':'아직 대화가 없습니다.')+'</h3><p>직원 목록에서 첫 대화를 시작하세요.</p></div>';}
if(list.innerHTML!==html){const old=document.activeElement?.dataset.mcThread||document.activeElement?.dataset.mcStaff;list.innerHTML=html;if(old)list.querySelector('[data-mc-thread="'+CSS.escape(old)+'"],[data-mc-staff="'+CSS.escape(old)+'"]')?.focus({preventScroll:true});}}
function setTab(next,{record=true}={}){tab=next;if(record&&frame()?.scene==='list')writeFrame({tab:next},true);app.dataset.screen='list';document.body.classList.remove('mc-chat-focused');app.dataset.tab=tab;node.querySelectorAll('[data-mc-tab]').forEach(b=>b.classList.toggle('active',b.dataset.mcTab===tab));drawList();if(!mobile&&current)app.dataset.screen='chat';}
function header(){if(!current)return;const p=peer(),name=roomName();$('[data-mc-peer]').innerHTML=roomAvatar(current)+'<span><strong>'+esc(name)+'</strong><small>'+esc(current.kind==='group'?'참여자 '+current.members.length+'명':p.subject||'직원 대화')+'</small></span>';const phone=mine()&&current.kind!=='group'?tel(p.phone):'';$('[data-mc-call]').hidden=!phone;if(phone)$('[data-mc-call]').href=phone;form.hidden=!mine()||!!search;}
function textHTML(text){const terms=String(text).split(/(https?:\/\/[^\s<>]+)/g);return terms.map((p,i)=>{if(i%2)return'<a href="'+esc(p)+'" target="_blank" rel="noopener noreferrer">'+esc(p)+'</a>';if(!search)return esc(p);const lower=p.toLowerCase(),needle=search.toLowerCase();let out='',at=0,n;while((n=lower.indexOf(needle,at))!==-1){out+=esc(p.slice(at,n))+'<mark>'+esc(p.slice(n,n+needle.length))+'</mark>';at=n+needle.length}return out+esc(p.slice(at))}).join('')}
function allRows(){if(search)return state()?.searchRows||[];const s=state();return [...(s?.rows||[]),...(outbox.get(current?.id)||[])];}
function drawMessages({bottom=false,prepend=false}={}){if(!current||!valid())return;const scroll=body.scrollTop,height=body.scrollHeight,s=state(),rows=allRows();let lastDay='';let html=(search?s.searchOlder:s.hasOlder)?'<button class="mc-older" data-mc-older>이전 메시지 보기</button>':'';
rows.forEach((m,i)=>{const k=day(m.created_at),previous=rows[i-1],next=rows[i+1],joined=previous&&previous.sender_id===m.sender_id&&day(previous.created_at)===k&&clock(previous.created_at)===clock(m.created_at),tail=!next||next.sender_id!==m.sender_id||clock(next.created_at)!==clock(m.created_at)||day(next.created_at)!==k,isMine=m.sender_id===uid;if(k!==lastDay){html+='<div class="mc-date"><span>'+esc(dateLabel(m.created_at))+'</span></div>';lastDay=k}html+='<article class="mc-message '+(isMine?'own':'')+' '+(joined?'joined':'')+'" data-mc-seq="'+esc(m.seq||m.request_id)+'">'+(!isMine?(!joined?'<button class="mc-message-avatar" data-mc-person="'+esc(m.sender_id)+'" aria-label="'+esc(m.sender_name)+' 프로필">'+avatar(m.sender_name,m.sender_id)+'</button>':'<span class="mc-message-avatar"></span>'):'')+'<div class="mc-message-main">'+(!isMine&&!joined?'<button class="mc-sender" data-mc-person="'+esc(m.sender_id)+'">'+esc(m.sender_name)+'</button>':'')+'<div class="mc-bubble">'+textHTML(m.content)+'</div><span class="mc-message-meta">'+(m.pending?m.failed?'<button data-mc-retry="'+esc(m.request_id)+'">다시 보내기</button>':'전송 중':tail?(isMine&&mine()?'<span class="mc-read">'+(current.kind==='group'?((s.readMarkers||[]).filter(x=>Number(x.joined_seq)<Number(m.seq)&&Number(x.last_seq)<Number(m.seq)).length||'읽음'):Number(m.seq)<=s.read?'읽음':'1')+'</span>':'')+'<time>'+esc(clock(m.created_at))+'</time>':'')+'</span></div><button class="mc-copy" data-mc-copy="'+esc(m.seq||m.request_id)+'" aria-label="메시지 복사">'+icon('copy')+'</button></article>'});
if(!rows.length)html+='<div class="mc-chat-empty">'+icon(search?'search':'chat')+'<p>'+(loading?'대화를 불러오는 중…':search?'이 내용의 메시지가 없습니다.':'아직 메시지가 없습니다.')+'</p></div>';
if(body.innerHTML!==html){body.innerHTML=html;body.scrollTop=prepend?scroll+body.scrollHeight-height:bottom?body.scrollHeight:scroll}else if(bottom)body.scrollTop=body.scrollHeight;
if(bottom){follow=true;$('[data-mc-jump]').hidden=true}if(search)$('[data-mc-status]').textContent=rows.length+'개의 검색 결과';}
function merge(r,older=false){const s=state(),target=search?'searchRows':'rows',map=new Map(s[target].map(m=>[m.seq,m]));r.rows.forEach(m=>map.set(m.seq,m));s[target]=[...map.values()].sort((a,b)=>Number(a.seq)-Number(b.seq));if(older||!s[target].length||!r.after)s[search?'searchOlder':'hasOlder']=r.has_older;s.read=Number(r.peer_last_read_seq||0);s.readMarkers=r.read_markers||[];if(!search){s.cursor=Math.max(s.cursor,...r.rows.map(m=>Number(m.seq)));const ids=new Set(s.rows.map(m=>m.request_id));outbox.set(current.id,(outbox.get(current.id)||[]).filter(m=>!ids.has(m.request_id)))} }
async function read(){if(!valid()||profile||!current||!mine()||search||document.hidden||mobile&&app.dataset.screen!=='chat'||!follow)return;const s=state(),tid=current.id,seq=s.cursor;if(!seq||seq<=s.lastRead||s.reading)return;s.reading=true;try{await call('read',{thread_id:tid,seen_seq:seq});s.lastRead=Math.max(s.lastRead,seq);if(!valid())return;const t=cache.rows.find(t=>t.id===tid);if(t)t.unread=0;paintBadge();drawList();MiraeInbox?.refresh()}catch{}finally{s.reading=false}}
