 const groups=[...dialog.querySelectorAll('.modal-body [data-dialog-actions]')],buttons=[...new Set(groups.flatMap(g=>[...g.querySelectorAll('button')]))];if(!buttons.length)return;
 let footer=dialog.querySelector(':scope > .modal-footer');if(!footer){footer=document.createElement('footer');footer.className='modal-footer';dialog.append(footer)}footer.classList.add('is-action-footer');
 for(const button of buttons){const form=button.closest('form');if(form){let id=form.getAttribute('id');if(!id){id='dialog-form-'+crypto.randomUUID();form.setAttribute('id',id);form.dataset.dialogForm=''}button.setAttribute('form',id)}if(button.classList.contains('danger')){button.classList.add('dialog-danger');footer.prepend(button)}else footer.append(button)}
