function batchPrint(initial={}){const owner=cfg.user()?.id,classes=cfg.base().classes,selected=new Set(),month=MiraeAttendanceCore.korea().date.slice(0,7);const n=cfg.modal('출석부 다중 출력','<form data-print-form><div class="print-month-range"><label>시작 월<input class="input" type="month" name="start" value="'+E(initial.start?.slice(0,7)||month)+'" required></label><span>—</span><label>종료 월<input class="input" type="month" name="end" value="'+E(initial.end?.slice(0,7)||month)+'" required></label></div><input class="input" type="search" data-print-search placeholder="반 이름 · 강사 검색" aria-label="출력할 반 검색"><label class="check-label print-select-all"><input type="checkbox" data-print-all>검색한 반 모두 선택</label><div class="print-class-list" data-print-classes></div><div class="print-selection" data-dialog-actions><strong data-print-count data-dialog-meta>0개 반 선택</strong><button class="btn primary" type="submit" disabled>출력하기</button></div><p class="inline-error" data-print-error role="status"></p></form>');const form=n.querySelector('form'),list=n.querySelector('[data-print-classes]'),button=form.querySelector('[type=submit]');MiraeDrafts.actions(n);let busy=false;
 const visible=()=>{const q=n.querySelector('[data-print-search]').value.trim().toLowerCase();return classes.filter(c=>!q||[c.name,cfg.base().teachers?.find(t=>t.id===c.teacher_id)?.name||''].join(' ').toLowerCase().includes(q))};function sync(){n.querySelector('[data-print-count]').textContent=selected.size+'개 반 선택';button.disabled=busy||!selected.size;const v=visible(),all=n.querySelector('[data-print-all]');all.checked=!!v.length&&v.every(c=>selected.has(c.id));all.indeterminate=v.some(c=>selected.has(c.id))&&!all.checked}function draw(){list.innerHTML=visible().map(c=>'<label><input type="checkbox" data-print-class="'+E(c.id)+'" '+(selected.has(c.id)?'checked':'')+'><span><strong>'+E(c.name)+'</strong><small>'+E(c.start_date)+' — '+E(c.end_date)+'</small></span></label>').join('')||'<div class="board-empty">일치하는 반이 없습니다.</div>';list.querySelectorAll('[data-print-class]').forEach(x=>x.onchange=()=>{x.checked?selected.add(x.dataset.printClass):selected.delete(x.dataset.printClass);sync()});sync()}n.querySelector('[data-print-search]').oninput=draw;n.querySelector('[data-print-all]').onchange=e=>{visible().forEach(c=>e.target.checked?selected.add(c.id):selected.delete(c.id));draw()};form.onsubmit=async e=>{e.preventDefault();if(busy||!selected.size||!form.reportValidity())return;const error=n.querySelector('[data-print-error]');busy=true;cfg.busy?.(true,n);sync();error.textContent='출력 자료를 불러오는 중';try{const r=await call('print-books',{class_ids:[...selected],start:form.start.value,end:form.end.value});if(cfg.user()?.id!==owner)return;error.textContent=r.sheets.length+'장의 출석부 준비 완료';await printSheets(r.sheets)}catch(err){error.textContent=err.message}finally{busy=false;cfg.busy?.(false,n);sync()}};draw();return n}
