let cfg={},owner='',account=null,accountTask=null,checked=false,checking=null,connection='idle',connectionNote='',classes=[],codes=[],classTime='',classTask=null,rosters=new Map(),rosterTasks=new Map(),histories=new Map(),historyTasks=new Map(),node=null,view='write',selected='',student='',serial=0,drafts=new Map(),saving=false,directory=[],directoryTime='',directoryTask=null,historyTime='';
function allowed(){return ['admin','teacher'].includes(cfg.user?.()?.role)&&cfg.can?.('consultations')}
function error(e){return Object.entries(errors).find(([k])=>String(e.code||e.message).includes(k))?.[1]||e.message}
