async function rpc(action,data={}){try{return await MiraePC.counselCall(action,data)}catch(e){e.message=error(e);throw e}}
async function getAccount(force=false){if(!force&&account)return account;if(accountTask)return accountTask;const who=owner,era=epoch;const p=rpc('account').then(r=>{if(owner===who&&epoch===era)account=r;return r}).finally(()=>{if(accountTask===p)accountTask=null});accountTask=p;return p}
async function job(kind,payload={},options={}){
 const who=identity(),era=epoch;if(!who)throw Error('임직원 로그인이 필요합니다.');
 if(MiraePC.state!=='connected'&&!await MiraePC.connect(false))throw Error('연결된 PC의 연결기를 실행해 주세요.');
 if((owner!==who||epoch!==era))throw Error('로그인 계정이 변경되었습니다.');
 let id=options.id||uuid(),d;
 if(!options.statusOnly){d=await rpc('submit',{id,kind,payload});id=d.id||id;}
 const until=Date.now()+18*60*1000;
 while(Date.now()<until&&owner===who&&epoch===era){
  try{d=await rpc('status',{id})}catch(e){if(e.code==='NETWORK_ERROR'||e.code==='RESPONSE_INVALID'){options.progress?.('연결 응답을 기다리는 중');await sleep(1500);continue}throw e}
  if((owner!==who||epoch!==era))throw Error('로그인 계정이 변경되었습니다.');
  options.progress?.(d.progress?.label||(d.state==='queued'?'PC에 요청 전달 중':'타임넷 응답 수신 중'),d.progress||{});
  if(['done','failed','unknown'].includes(d.state)){if(d.result?.ok)return {...d.result,request_id:id};const e=Error(d.result?.message||(d.state==='unknown'?'결과를 확인하지 못했습니다. 결과 확인을 눌러 주세요.':'타임넷 요청을 완료하지 못했습니다.'));e.uncertain=d.state==='unknown';e.definitive=d.state==='failed';throw e}
  await sleep(650);
 }
 const e=Error('응답을 기다리는 시간이 길어지고 있습니다. 결과 확인을 눌러 주세요.');e.uncertain=true;throw e;
}
function paintConnection(){if(!node?.isConnected)return;const b=node.querySelector('[data-tn-account]');if(!b)return;const label=connection==='checking'?'로그인 확인 중':connection==='ok'?'타임넷 연결됨':connection==='error'?'타임넷 연결 확인':'개인 타임넷 연결';b.innerHTML=(connection==='checking'?'<span class="state-spinner"></span>':'<i class="tn-dot"></i>')+E(label);b.classList.toggle('tn-alert',connection==='error');b.title=connectionNote||account?.username||label}
async function start(){if(!identity()||checked)return checking;if(checking)return checking;const who=owner,era=epoch;
 const task=(async()=>{try{const a=await getAccount();if((owner!==who||epoch!==era)||!a.configured)return;if(MiraePC.state!=='connected')return;connection='checking';paintConnection();await job('verify');if((owner!==who||epoch!==era))return;connection='ok';checked=true;connectionNote='로그인 확인 완료';await getAccount(true);void loadClasses().catch(()=>{})}catch(e){if(owner===who&&epoch===era){connection='error';connectionNote=error(e);checked=true}}finally{paintConnection()}})();checking=task;try{await task}finally{if(checking===task)checking=null}
}
async function loadClasses(force=false){if(classTask)return classTask;if(!force&&classes.length)return classes;const who=owner,era=epoch;const p=job('classes').then(r=>{if(owner===who&&epoch===era){classes=r.classes||[];codes=r.codes||[];classTime=r.fetched_at}return r.classes||[]}).finally(()=>{if(classTask===p)classTask=null});classTask=p;return p}
async function roster(c,force=false){const k=key(c),hit=rosters.get(k);if(!force&&hit)return hit;if(rosterTasks.has(k))return rosterTasks.get(k);const who=owner,era=epoch;const p=job('students',{center:c.ACAD_CD,class:c.CLASS_CD}).then(r=>{if(owner===who&&epoch===era){rosters.set(k,r);directory=directory.filter(s=>key(s)!==k).concat(r.students||[]);indexDirectory()}return r}).finally(()=>{if(rosterTasks.get(k)===p)rosterTasks.delete(k)});rosterTasks.set(k,p);return p}
function currentClass(){return classes.find(c=>key(c)===selected)}
function currentStudents(){return [...(rosters.get(selected)?.students||[])].sort((a,b)=>Number(withdrawn(a))-Number(withdrawn(b))||nameOrder.compare(a.NM||'',b.NM||'')||nameOrder.compare(a.SCH_NM||'',b.SCH_NM||'')||nameOrder.compare(a.STD_NO||'',b.STD_NO||''))}
