function drawContent(){if(!node?.isConnected)return;requestAnimationFrame(fitWorkspace);const writing=view==='write'&&cfg.can('consultation_edit');node.querySelector('.tn-workspace').classList.toggle('tn-writing',writing);node.querySelector('.tn-workspace').classList.toggle('tn-overview',view==='overview');node.querySelectorAll('[data-refresh-directory],[data-refresh-history],[data-tn-account],[data-tn-state]').forEach(b=>b.hidden=view==='overview');node.querySelectorAll('[data-tn-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tnTab===view);b.setAttribute('aria-selected',String(b.dataset.tnTab===view))});node.querySelector('[data-tn-directory-count]').textContent=directoryTime?new Set(directory.map(s=>s.STD_NO)).size+'명 · '+classes.length+'개 반':'';paintTimes();const content=node.querySelector('[data-tn-content]'),c=currentClass();if(view==='overview'){node.querySelector('[data-tn-directory-count]').textContent='';MiraeCounselOverview.mount(content);return}if(writing){if(!directoryTime){content.innerHTML='<div class="tn-loading" role="status"><span class="state-spinner"></span><strong>학생 명단 준비 중</strong></div>';return}drawWriter(content);return}if(!c){content.innerHTML=empty('조회 가능한 반이 없습니다.');return}if(!rosters.has(selected)){content.innerHTML='<div class="tn-loading"><span class="state-spinner"></span><strong>반 구성원 확인 중</strong></div>';return}drawHistory(content,c)}
function defaultPeriod(){const p=MiraeAttendanceCore.korea();return{date:p.date,time:new Date().toLocaleTimeString('en-GB',{timeZone:'Asia/Seoul',hour:'2-digit',minute:'2-digit'}),method:'02',target:'01',type:'04',detail:'13'}}
