function remember(){const d=drafts.get('all');if(d)MiraeDrafts.setModel('timenet-counsel:all',d)}
function codeOptions(group,value,parent=''){return codes.filter(c=>c.CD_CLASS===group&&(!parent||c.UPPER_CD===parent)).map(c=>'<option value="'+E(c.CD)+'" '+(c.CD===value?'selected':'')+'>'+E(c.CD_NM)+'</option>').join('')}
function indexDirectory(){directoryIndex.clear();studentClasses.clear();const byClass=new Map(classes.map(c=>[key(c),c]));for(const s of directory){for(const q of [s.NM,s.STD_NO,studentLabel(s)]){if(!directoryIndex.has(q))directoryIndex.set(q,new Map());directoryIndex.get(q).set(s.STD_NO,s)}if(!studentClasses.has(s.STD_NO))studentClasses.set(s.STD_NO,new Map());const c=byClass.get(key(s));if(c&&!withdrawn(s))studentClasses.get(s.STD_NO).set(key(c),c)}}
