function dateNumber(value){const v=String(value||'').replace(/-/g,'').slice(0,8);if(!/^\d{8}$/.test(v))return null;const y=+v.slice(0,4),m=+v.slice(4,6),d=+v.slice(6,8),t=Date.UTC(y,m-1,d);const check=new Date(t);return check.getUTCFullYear()===y&&check.getUTCMonth()===m-1&&check.getUTCDate()===d?t:null}
