function expectedHomework(){const cache=derivedCache();if(cache.homework)return cache.homework;const out=[],students=new Map(S.base.students.map(s=>[s.id,s])),classes=new Map(S.base.classes.map(c=>[c.id,c])),enrollments=new Map(),latest=new Map(),photos=new Map();for(const e of S.base.enrollments){if(!enrollments.has(e.class_id))enrollments.set(e.class_id,[]);enrollments.get(e.class_id).push(e)}for(const sub of S.data.submissions){const key=sub.lesson_id+'_'+sub.student_id;if(!latest.has(key)||new Date(latest.get(key).submitted_at)<new Date(sub.submitted_at))latest.set(key,sub)}for(const f of S.data.attachments){if(!photos.has(f.submission_id))photos.set(f.submission_id,[]);photos.get(f.submission_id).push(f)}for(const l of S.data.lessons){if(!l.online_required||l.published===false)continue;for(const e of enrollments.get(l.class_id)||[]){if(!relevantEnrollment(e,l)||(isFamily()&&e.student_id!==childID()))continue;const s=students.get(e.student_id)||getStudent(e.student_id),sub=latest.get(l.id+'_'+s.id),due=new Date(l.due_at)<new Date();out.push({id:l.id+'_'+s.id,lesson_id:l.id,student_id:s.id,lesson:l,student:s,submission:sub,name:s.name,class_name:classes.get(l.class_id)?.name||'',title:l.title||l.progress,status:sub?.status||'missing',due_at:l.due_at,submitted_at:sub?.submitted_at||'',late:!!sub?.late,overdue:(!sub||sub.status==='missing')&&due,files:sub?photos.get(sub.id)||[]:[]})}}cache.homework=out;return out}
function studentMetrics(sid){const cache=derivedCache();if(cache.metrics.has(sid))return cache.metrics.get(sid);const ex=new Map(S.data.exams.map(x=>[x.id,x]));const scored=S.data.scores.filter(s=>s.student_id===sid&&!s.absent&&s.score!==null&&s.score!==''&&ex.has(s.exam_id)).map(s=>({...s,exam:ex.get(s.exam_id),pct:Number(s.score)/Number(ex.get(s.exam_id).max_score)*100})).sort((a,b)=>a.exam.exam_date.localeCompare(b.exam.exam_date)||a.exam.id.localeCompare(b.exam.id));const pts=scored.map(s=>s.pct),hw=expectedHomework().filter(h=>h.student.id===sid),due=hw.filter(h=>new Date(h.due_at)<new Date()),feedback=S.data.feedback.filter(f=>f.student_id===sid),delta=pts.length>=6?avg(pts.slice(-3))-avg(pts.slice(-6,-3)):pts.length>=2?pts.at(-1)-pts[0]:null;const result={sid,scored,average:avg(pts),latest:pts.at(-1)??null,delta,count:pts.length,missing:due.filter(h=>!h.submission||h.status==='missing').length,submitted:hw.filter(h=>h.submission&&h.status!=='missing').length,homework:hw.length,passed:hw.filter(h=>h.status==='passed').length,passRate:hw.length?hw.filter(h=>h.status==='passed').length/hw.length*100:null,absence:feedback.filter(f=>f.attendance==='absent').length,attendance:feedback.some(f=>f.attendance!=='unrecorded')?feedback.filter(f=>['present','late'].includes(f.attendance)).length/feedback.filter(f=>f.attendance!=='unrecorded').length*100:null,feedback};cache.metrics.set(sid,result);return result}
function reportRows(){const ids=new Set(S.base.enrollments.filter(e=>(!S.classId||e.class_id===S.classId)&&(!S.criteria.currentOnly||e.status==='enrolled')).map(e=>e.student_id));return S.base.students.filter(s=>ids.has(s.id)).map(s=>{const m=studentMetrics(s.id),c=S.criteria,checks=[];if(c.averageOn)checks.push({hit:m.count>=c.minimum&&m.average!==null&&m.average<c.average,label:'평균 미달'});if(c.dropOn)checks.push({hit:m.count>=c.minimum&&m.delta!==null&&m.delta<=-c.drop,label:'성적 하락'});if(c.missingOn)checks.push({hit:m.missing>=c.missing,label:'과제 누락'});if(c.absenceOn)checks.push({hit:m.absence>=c.absence,label:'결석 누적'});const matched=checks.length>0&&(c.logic==='all'?checks.every(x=>x.hit):checks.some(x=>x.hit));return {...s,...m,reasons:checks.filter(x=>x.hit).map(x=>x.label),matched,signal:matched?checks.filter(x=>x.hit).length:0}})}
