function dashboardClasses(){const day=today(),mode=S.dashboardScope||'homeroom';return S.base.classes.filter(c=>c.status==='active'&&(!c.start_date||c.start_date<=day)&&(!c.end_date||c.end_date>=day)).filter(c=>mode==='all'||c.teacher_id===S.user.id||mode==='team'&&MiraeTeam.has(c,S.user.id))}
function renderDashboard(){if(isFamily())return renderDashboardAll();S.dashboardScope||='homeroom';const oldBase=S.base,oldData=S.data,oldClass=S.classId,classes=dashboardClasses(),ids=new Set(classes.map(c=>c.id)),enrollments=S.base.enrollments.filter(e=>ids.has(e.class_id)&&e.status==='enrolled'&&(!e.joined_on||e.joined_on<=today())&&(!e.left_on||e.left_on>=today())),students=new Set(enrollments.map(e=>e.student_id)),lessons=S.data.lessons.filter(l=>ids.has(l.class_id)),lids=new Set(lessons.map(l=>l.id)),exams=S.data.exams.filter(e=>ids.has(e.class_id)),eids=new Set(exams.map(e=>e.id));
 try{S.base={...oldBase,classes,enrollments,students:oldBase.students.filter(s=>students.has(s.id))};S.data={...oldData,lessons,exams,scores:oldData.scores.filter(s=>eids.has(s.exam_id)&&students.has(s.student_id)),feedback:oldData.feedback.filter(f=>lids.has(f.lesson_id)&&students.has(f.student_id)),submissions:oldData.submissions.filter(s=>lids.has(s.lesson_id)&&students.has(s.student_id)),consultations:oldData.consultations.filter(c=>ids.has(c.class_id)&&students.has(c.student_id)),videos:oldData.videos.filter(v=>ids.has(v.class_id))};if(!ids.has(S.classId))S.classId='';renderDashboardAll();const main=$('#main'),tabs=document.createElement('div');tabs.className='dashboard-scope-tabs';tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','오늘의 클래스 표시 범위');tabs.innerHTML=[['all','전체'],['homeroom','담임반'],['team','담임+부담임반']].map(([v,n])=>'<button type="button" role="tab" aria-selected="'+(S.dashboardScope===v)+'" data-dashboard-scope="'+v+'" class="'+(S.dashboardScope===v?'active':'')+'">'+n+'</button>').join('');main.querySelector('.page-head')?.after(tabs);tabs.querySelectorAll('button').forEach(b=>b.onclick=()=>{S.dashboardScope=b.dataset.dashboardScope;S.classId='';renderPage()});if(!classes.length){const note=document.createElement('div');note.className='dashboard-scope-empty';note.textContent=S.dashboardScope==='homeroom'?'현재 운영 중인 담임반이 없습니다.':S.dashboardScope==='team'?'현재 운영 중인 담임·부담임반이 없습니다.':'조회할 수 있는 운영 반이 없습니다.';tabs.after(note);}}
 finally{S.base=oldBase;S.data=oldData;S.classId=oldClass;}
}

function feedbackList(sid){const fs=S.data.feedback.filter(f=>f.student_id===sid&&f.comment).sort((a,b)=>b.created_at.localeCompare(a.created_at)).slice(0,4);return fs.length?`<div class="line-list">${fs.map(f=>{const l=S.data.lessons.find(x=>x.id===f.lesson_id);return`<div class="notice-row"><small>${dateText(l?.lesson_date)} · ${esc(getClass(l?.class_id).name)}</small>${commentBlock(f.comment)}</div>`}).join('')}</div>`:empty('등록된 코멘트가 없습니다.')}
function lineLessons(rows){return rows.length?`<div class="line-list">${rows.map(l=>`<div class="line-row"><div class="date-stamp"><small>${new Date(l.lesson_date).getMonth()+1}월</small><strong>${l.lesson_date.slice(-2)}</strong></div><div class="line-content"><div class="line-title">${esc(l.title||l.progress||'수업 기록')} ${l.online_required?badge('submitted','온라인 과제'):''}</div><div class="line-description">${esc(getClass(l.class_id).name)} · ${esc(l.progress)}</div>${isFamily()&&S.data.feedback.find(f=>f.lesson_id===l.id&&f.student_id===childID())?.comment?`<div class="lesson-comment-preview">${commentBlock(S.data.feedback.find(f=>f.lesson_id===l.id&&f.student_id===childID()).comment)}</div>`:''}</div><div class="line-actions">${ib('chevron','lesson-detail',`data-id="${l.id}"`,'수업 내용 보기')}</div></div>`).join('')}</div>`:empty('등록된 수업이 없습니다.')}
function lineHomework(rows){return rows.length?`<div class="line-list">${rows.map(h=>`<div class="line-row"><span class="avatar">${icon('homework',17)}</span><div class="line-content"><div class="line-title">${esc(h.title||'과제')} ${badge(h.status)}</div><div class="line-description ${h.overdue?'red':''}">${h.overdue?'제출 기한이 지났습니다 · ':''}${timeText(h.due_at)}까지 · ${esc(h.lesson.homework)}</div></div><div class="line-actions">${btn(h.submission?'제출 내역':'과제 제출','homework-detail',`data-id="${h.id}"`,h.submission?'sm':'primary sm')}</div></div>`).join('')}</div>`:empty('확인할 과제가 없습니다.')}
function studentCell(s){if(['students','reports'].includes(S.view))s={...s,student_no:''};return`<div class="flex"><span class="avatar">${esc(s.name.slice(-2))}</span><span><span class="primary-text">${esc(s.name)}</span><small>${esc(s.student_no||'')}</small></span></div>`}
function simpleTable(cols,rows){return`<div class="table-shell"><div class="table-scroll"><table class="data-table"><thead><tr>${cols.map(c=>`<th>${c.label}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>`<td>${c.render?c.render(r):esc(r[c.key])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`}
function rowsForView(){const view=S.view,student=isFamily();switch(view){case'students':return S.base.students.filter(s=>!s.account_deleted).filter(s=>!S.classId||S.base.enrollments.some(e=>e.student_id===s.id&&e.class_id===S.classId)).map(s=>{const es=S.base.enrollments.filter(e=>e.student_id===s.id&&(!S.classId||e.class_id===S.classId));return {...s,parent_connection:parentState(s).label,parent_login:(S.base.parents||[]).find(p=>p.id===s.parent_id)?.login_id||'',class_names:es.map(e=>getClass(e.class_id).name).join(', '),status:S.classId?(es[0]?.status||''):s.active?'active':'inactive'}});case'classes':return S.base.classes.filter(c=>isFamily()||!S.classId||c.id===S.classId).map(c=>({...c,assistant_name:MiraeTeam.assistants(c).map(id=>staffName(id)).join(', '),homework_scheme_label:HW_SCHEMES[homeworkMode(c.homework_scheme)],teacher_name:S.base.teachers.find(t=>t.id===c.teacher_id)?.name||S.accounts.find(t=>t.id===c.teacher_id)?.name||'',count:!isFamily()&&!can('all_classes')&&!MiraeTeam.has(c,S.user.id)?null:enrollForClass(c.id).filter(e=>e.status==='enrolled').length}));case'lessons':return S.data.lessons.map(l=>({...l,class_name:getClass(l.class_id).name,status:l.published?'active':'inactive'}));case'exams':return S.data.exams.map(e=>{const ss=S.data.scores.filter(s=>s.exam_id===e.id),mine=ss.find(s=>s.student_id===childID());return {...e,class_name:getClass(e.class_id).name,count:ss.filter(s=>s.score!==null&&!s.absent).length,mean:S.data.exam_stats[e.id]?.mean??null,score:mine?.score??null,status:mine?.absent?'absent':e.published?'active':'inactive'}});case'homework':return expectedHomework();case'consultations':return S.data.consultations.map(c=>({...c,name:getStudent(c.student_id).name,class_name:getClass(c.class_id).name}));case'videos':return S.data.videos.map(v=>({...v,class_name:getClass(v.class_id).name,status:v.published?'active':'inactive'}));case'parents':return S.parents.filter(p=>p.status!=='deleted').map(p=>({...p,child_names:(p.children||[]).filter(c=>!c.account_deleted).map(c=>c.name).join(', '),...parentCourseState(p)}));case'accounts':return S.accounts;case'audit':return (S.audit||[]).map(x=>({...x,name:S.base.teachers.find(t=>t.id===x.actor_id)?.name||S.accounts.find(t=>t.id===x.actor_id)?.name||'사용자',fields:x.fields?.join(', ')||''}));case'reports':return reportRows().filter(r=>!S.criteria.only||r.matched);default:return[]}}
function columnsFor(view=S.view){const student=isFamily();const classcol={key:'class_name',label:'강좌'};const action=(act,key='id',label='상세')=>({key:'_action',label:'',render:r=>ib('chevron',act,`data-id="${r[key]}"`,label)});const datecol=(key,label)=>({key,label,render:r=>dateText(r[key],true)});switch(view){case'students':return [{key:'name',label:'학생명',editable:can('student_edit'),render:studentCell},{key:'parent_connection',label:'학부모 계정',render:r=>parentConnection(r)+MiraePhoneReview.badge(r.id)},...(can('sms')||can('attendance_notify')||can('mswitch_contact')?[{key:'sms_connection',label:'문자 연결',render:smsConnection}]:[]),{key:'school',label:'학교',editable:can('student_edit')},{key:'grade',label:'학년',editable:can('student_edit')},{key:'class_names',label:'강좌'},{key:'status',label:'상태',render:r=>badge(r.status)},action('student-detail')];case'classes':return [{key:'name',label:'강좌명',editable:!student&&can('classes_all_edit'),render:r=>`<span class="primary-text">${esc(r.name)}</span>`},{key:'subject',label:'과목'},{key:'teacher_name',label:'담임'},{key:'assistant_name',label:'부담임'},{key:'homework_scheme_label',label:'과제 검사 방식'},datecol('start_date','개강일'),datecol('end_date','종강일'),{key:'count',label:'재원',render:r=>r.count===null?'—':r.count+'명'},{key:'status',label:'운영',render:r=>badge(r.status)},{key:'plan',label:'강의계획',render:r=>btn('강의계획 보기','syllabus-view',`data-id="${r.id}"`,'sm')+(!student&&canEditSyllabus(r)?btn('강의계획 편집','syllabus-edit',`data-id="${r.id}"`,'sm'):'')},action(student||!can('class_edit')?'select-class':'edit')];case'lessons':return [datecol('lesson_date','수업일'),classcol,{key:'title',label:'수업',editable:!student&&can(EDIT_CAP[S.view]||'lesson_edit'),render:r=>`<span class="primary-text">${esc(r.title||r.progress||'수업 기록')}</span>`},{key:'progress',label:'진도',editable:!student&&can(EDIT_CAP[S.view]||'lesson_edit')},{key:'homework',label:'과제',editable:!student&&can(EDIT_CAP[S.view]||'lesson_edit')},{key:'online_required',label:'제출 방식',render:r=>r.online_required?badge('submitted','온라인 숙제'):'일반 숙제'},{key:'due_at',label:'제출 기한',render:r=>r.online_required?timeText(r.due_at):'—'},...(student?[{key:'my_comment',label:(S.user.role==='student'?'내 수업 코멘트':'자녀 수업 코멘트'),render:r=>commentBlock(S.data.feedback.find(f=>f.lesson_id===r.id&&f.student_id===childID())?.comment)}]:[]),{key:'materials',label:'수업 자료',render:r=>{const n=(S.data.lesson_files||[]).filter(f=>f.lesson_id===r.id&&!f.deleted).length;return n?n+'개':'—'}},action('lesson-detail')];case'exams':return [datecol('exam_date','시험일'),classcol,{key:'title',label:'시험명',render:r=>`<span class="primary-text">${esc(r.title)}</span>`},{key:'unit',label:'단원'},{key:'max_score',label:'만점',render:r=>fmt(r.max_score)+'점'},student?{key:'score',label:'내 점수',render:r=>r.status==='absent'?badge('absent','미응시'):`<span class="primary-text">${fmt(r.score)}점</span>`}:{key:'count',label:'응시',render:r=>r.count+'명'},...(student?[{key:'homework_grade',label:'과제 검사',render:r=>esc(gradeLabel(S.data.feedback.find(f=>f.lesson_id===r.lesson_id&&f.student_id===childID())?.homework_grade,r.class_id,r.lesson_id))}]:[]),{key:'mean',label:'반 평균',render:r=>fmt(r.mean)+'점'},action(student?'exam-detail':'score-entry', 'id',student?'성적 확인':'점수 입력')];case'homework':return [...(!student?[{key:'name',label:'학생',render:r=>studentCell(r.student)},classcol]:[]),{key:'title',label:'과제',render:r=>`<span class="primary-text">${esc(r.title)}</span>`},{key:'status',label:'상태',render:r=>badge(r.status)},{key:'due_at',label:'제출 기한',render:r=>`<span class="${r.overdue?'red':''}">${timeText(r.due_at)}</span>`},{key:'submitted_at',label:'제출 일시',render:r=>`${timeText(r.submitted_at)} ${r.late?badge('poor','지각 제출'):''}`},{key:'files',label:'사진',plain:r=>r.files.length,render:r=>r.files.length?r.files.length+'장':'—'},action('homework-detail')];case'consultations':return [...(!student?[{key:'name',label:'학생'}]:[]),{key:'created_at',label:'신청일',render:r=>timeText(r.created_at)},classcol,{key:'category',label:'상담 유형'},{key:'reason',label:'상담 내용'},{key:'preferred_at',label:'희망 · 예약',render:r=>timeText(r.preferred_at)},{key:'status',label:'진행',render:r=>badge(r.status)},action('consult-detail')];case'videos':return [datecol('video_date','수업일'),classcol,{key:'title',label:'영상',render:r=>`<span class="flex"><span class="youtube">▶</span><span class="primary-text">${esc(r.title)}</span></span>`},{key:'position',label:'재생 위치',plain:r=>S.data.video_progress.find(p=>p.video_id===r.id&&p.student_id===childID())?.position_seconds||0,render:r=>{const p=S.data.video_progress.find(p=>p.video_id===r.id&&p.student_id===childID());return p?Math.floor(p.position_seconds/60)+'분 '+Math.floor(p.position_seconds%60)+'초':'—'}},{key:'_action',label:'',render:r=>`<div class="flex">${btn('재생','play-video',`data-id="${r.id}"`,'sm','videos')}${!student&&can('video_edit')?ib('edit','edit',`data-id="${r.id}"`,'영상 수정'):''}</div>`}];case'parents':return [{key:'name',label:'학부모',render:studentCell},{key:'child_names',label:'배정된 학생'},{key:'current_course_count',label:'현재 수강',plain:r=>r.current_course_count,render:r=>r.current_course_count?'<span class="connection-state ok">수강 중 · '+r.current_course_count+'개</span>':'<span class="connection-state muted">수강 강좌 없음</span>'},{key:'current_course_names',label:'현재 강좌'},{key:'phone',label:'연락처',render:r=>esc(r.phone||'—')+(r.children||[]).map(c=>MiraePhoneReview.badge(c.id,c.name)).join('')},{key:'login_id',label:'학부모 아이디'},{key:'status',label:'계정',render:r=>badge(r.status)},{key:'app_status',label:'앱 알림',render:r=>window.MiraePush.rows.some(x=>x.id===r.id)?window.MiraePushUI.badge(r.id):'—'},{key:'_action',label:'',render:r=>btn('정보 확인','parent-detail',`data-id="${r.id}"`,'ghost sm','chevron')}];case'accounts':return [{key:'name',label:'강사',render:r=>studentCell(r)},{key:'login_id',label:'아이디'},{key:'rank_level',label:'직급',plain:r=>window.MiraeRoles.level(r,S.base.role_policy),render:r=>window.MiraeRoles.level(r,S.base.role_policy)+' · '+esc(rankName(r))},{key:'login_history_scope',label:'로그인 이력 조회',render:r=>esc(({none:'조회 불가',own:'내 강좌 학생·학부모',all:'모든 사용자'})[r.login_history_scope]|| (window.MiraeRoles.allows(r,'login_history_all',S.base.role_policy)?'모든 사용자':window.MiraeRoles.allows(r,'login_history_own',S.base.role_policy)?'내 강좌 학생·학부모':'조회 불가'))},{key:'subject_scope',label:'관리 과목',render:r=>esc(window.MiraeSubject.label(r))},{key:'status',label:'재직 상태',render:r=>badge(r.status)},datecol('created_at','등록일'),{key:'_action',label:'',render:r=>r.role==='admin'&&!isSuper()?'':ib('edit','edit','data-id="'+r.id+'"','수정')}];case'audit':return [{key:'created_at',label:'변경 시각',render:r=>timeText(r.created_at)},{key:'name',label:'사용자'},{key:'entity',label:'항목'},{key:'action',label:'작업',render:r=>r.action==='insert'?'신규 등록':'수정'},{key:'fields',label:'변경한 필드'}];case'reports':return [{key:'name',label:'학생',render:studentCell},{key:'school',label:'학교 · 학년',render:r=>esc(r.school)+' '+esc(r.grade)},{key:'school_trend',label:'내신성적',render:r=>MiraeGradeHistory.badge(r.id,gradeBasis())},{key:'average',label:'평균',render:r=>fmt(r.average)+'점'},{key:'latest',label:'최근',render:r=>fmt(r.latest)+'점'},{key:'delta',label:'변화',render:r=>r.delta===null?'—':`<span class="${r.delta<0?'red':'green'}">${r.delta>0?'+':''}${fmt(r.delta)}점</span>`},{key:'missing',label:'기한 초과',render:r=>r.missing?`<span class="red">${r.missing}건</span>`:'—'},{key:'passRate',label:'과제 통과',render:r=>fmt(r.passRate,0)+'%'},{key:'absence',label:'결석',render:r=>r.absence+'회'},{key:'signal',label:'관리 신호',render:r=>`<span class="signal ${r.matched?'on':''}"><i class="dot"></i>${r.matched?r.reasons.join(' · '):'—'}</span>`},action('student-report')];default:return[]}}
function allFilteredRows(){let rows=rowsForView();if(S.view==='consultations'){ensureConsultDates();rows=rows.filter(r=>{const day=new Date(r.created_at).toLocaleDateString('sv-SE',{timeZone:'Asia/Seoul'});return day>=S.consultStart&&day<=S.consultEnd})}const q=S.q.trim().toLowerCase();if(q)rows=rows.filter(r=>columnsFor().some(c=>String(c.plain?c.plain(r):r[c.key]??'').toLowerCase().includes(q)));if(S.filter)rows=rows.filter(r=>r.status===S.filter);if(S.view==='parents'&&S.parentCourseFilter)rows=rows.filter(r=>S.parentCourseFilter==='yes'?r.current_course_count>0:r.current_course_count===0);const cols=columnsFor();if(S.sort.length)rows=[...rows].sort((a,b)=>{for(const {key,dir}of S.sort){const col=cols.find(c=>c.key===key);const aa=col?.plain?col.plain(a):a[key],bb=col?.plain?col.plain(b):b[key];let n;if(aa==null&&bb==null)n=0;else if(aa==null)n=1;else if(bb==null)n=-1;else n=typeof aa==='number'&&typeof bb==='number'?aa-bb:String(aa).localeCompare(String(bb),'ko',{numeric:true});if(n)return n*dir}return 0});return rows}
function renderGridZone(){const draft=MiraeDrafts.data.get('grid|'+S.user.id+'|'+S.view);if(draft&&!S.pending.size){S.pending=new Map(draft.pending);S.editing=draft.editing}const zone=$('#grid-zone');if(!zone)return;const cols=columnsFor();const statusOptions=S.view==='parents'?['active','inactive']:[...new Set(rowsForView().map(r=>r.status).filter(Boolean))];zone.innerHTML=`<div class="table-shell"><div class="table-tools"><div class="search-wrap">${icon('search',14)}<input id="grid-search" class="input search small" placeholder="${S.view==='students'?'이름 · 학교 검색':'목록 검색'}" value="${esc(S.q)}" aria-label="목록 검색"></div>${statusOptions.length>1?`<select class="input small" id="status-filter" aria-label="상태 필터"><option value="">전체 상태</option>${statusOptions.map(k=>`<option value="${esc(k)}" ${S.filter===k?'selected':''}>${esc(badges[k]?.[0]||k)}</option>`).join('')}</select>`:''}${S.view==='parents'?`<select class="input small" id="parent-course-filter" aria-label="현재 수강 필터"><option value="">전체 수강 상태</option><option value="yes" ${S.parentCourseFilter==='yes'?'selected':''}>현재 수강 중</option><option value="no" ${S.parentCourseFilter==='no'?'selected':''}>수강 강좌 없음</option></select>`:''}<div class="tool-right">${!isFamily()&&cols.some(c=>c.editable)?btn(S.editing?'편집 종료':'셀 편집','toggle-edit','','ghost sm hide-mobile','edit'):''}${S.pending.size?btn(S.pending.size+'행 저장','save-grid','','primary sm','check'):''}${btn('내보내기','export','','ghost sm hide-mobile','download')}${ib('settings','column-settings','','열 · 행 간격 설정')}</div></div><div id="grid-summary"></div><div id="grid-selection"></div><div id="data-grid"></div><div id="grid-footer"></div></div>`;drawGrid()}
function drawGrid(){queueMicrotask(()=>{MiraePhoneReview.paint();MiraeGradeHistory.paint()});const rows=allFilteredRows(),allcols=columnsFor(),hidden=S.hidden[S.view]||[],order=S.order[S.view]||[];const cols=allcols.filter(c=>!hidden.includes(c.key)).sort((a,b)=>{const ai=order.indexOf(a.key),bi=order.indexOf(b.key);return(ai<0?100+allcols.indexOf(a):ai)-(bi<0?100+allcols.indexOf(b):bi)});S.page=Math.min(S.page,Math.max(1,Math.ceil(rows.length/S.pageSize)));const page=rows.slice((S.page-1)*S.pageSize,S.page*S.pageSize),grid=$('#data-grid');if(!grid)return;const selectable=!isFamily()&&!['audit','reports'].includes(S.view)&&(S.view!=='consultations'||can('consultation_delete'))&&(S.view!=='parents'||can('parent_status')||can('parent_delete'));paintGridSummary(rows);updateGridSelection(rows);if(!page.length)grid.innerHTML=empty(S.q?'검색 결과가 없습니다.':'등록된 항목이 없습니다.');else if(S.view==='classes'&&isFamily()&&S.mode==='list'){grid.innerHTML='<div class="family-course-list">'+page.map(r=>{const p=(S.base.course_progress||[]).find(x=>x.class_id===r.id);return '<article class="family-course-row" data-row-id="'+esc(r.id)+'"><div class="family-course-title"><strong title="'+esc(r.name)+'">'+esc(r.name)+'</strong><span class="badge">'+esc(p?.state||'진행중')+'</span></div><div class="family-course-teacher">'+esc(r.teacher_name||'담당 강사')+'<span>'+esc(r.start_date||'')+' ~ '+esc(r.end_date||'')+'</span></div><div class="family-course-bottom">'+MiraeCourses.progress(p)+btn('수업 기록','course-open','data-id="'+esc(r.id)+'" data-tab="records"','sm')+'</div></article>'}).join('')+'</div>'}else if(S.mode==='list'){grid.innerHTML=`<div>${page.map(r=>{const cs=cols.filter(c=>c.key!=='_action'),first=cs.find(c=>c.key==='name'||c.key==='title')||cs[0];const secondary=cs.filter(c=>c!==first).slice(0,3);return`<div class="line-row ${S.selected.has(r.id)?'selected':''} ${r.matched?'flagged':''}" data-row-id="${r.id}">${selectable?`<input type="checkbox" class="row-check" data-draft-ignore data-id="${r.id}" ${S.selected.has(r.id)?'checked':''} aria-label="항목 선택">`:''}<div class="line-content"><div class="line-title">${first.render?first.render(r):esc(r[first.key])}${r.matched?`<span class="signal on"><i class="dot"></i>${r.reasons.join(' · ')}</span>`:''}</div><div class="line-description">${secondary.map(c=>(c.render?c.render(r):esc(r[c.key]))).join(' &nbsp;·&nbsp; ')}</div></div>${cols.find(c=>c.key==='_action')?.render(r)||''}</div>`}).join('')}</div>`}else{grid.innerHTML=`<div class="table-scroll" tabindex="0" id="table-focus"><table class="data-table"><thead><tr>${selectable?`<th class="check-cell"><input type="checkbox" id="select-page" data-draft-ignore aria-label="현재 조건 전체 선택" ${rows.every(r=>S.selected.has(r.id))?'checked':''}></th>`:''}<th class="index-cell">#</th>${cols.map(c=>`<th data-sort="${c.key}" data-col="${c.key}" draggable="${c.key!=='_action'}" ${c.key==='_action'?'class="row-actions"':''} aria-sort="${S.sort.find(x=>x.key===c.key)?S.sort.find(x=>x.key===c.key).dir>0?'ascending':'descending':'none'}">${c.label}${S.sort.some(x=>x.key===c.key)?` <span class="blue">${S.sort.find(x=>x.key===c.key).dir>0?'↑':'↓'}</span>`:''}</th>`).join('')}</tr></thead><tbody>${page.map((r,ri)=>`<tr data-row-id="${r.id}" class="${S.selected.has(r.id)?'selected':''} ${r.matched?'flagged':''}">${selectable?`<td class="check-cell"><input class="row-check" data-draft-ignore type="checkbox" data-id="${r.id}" ${S.selected.has(r.id)?'checked':''} aria-label="${esc(r.name||r.title||'항목')} 선택"></td>`:''}<td class="index-cell">${(S.page-1)*S.pageSize+ri+1}</td>${cols.map(c=>`<td ${c.key==='_action'?'class="row-actions"':''}>${S.editing&&c.editable?`<input class="cell-input ${S.pending.get(r.id)?.[c.key]!==undefined?'dirty':''}" data-row="${r.id}" data-field="${c.key}" value="${esc(S.pending.get(r.id)?.[c.key]??r[c.key])}" aria-label="${esc(c.label)}">`:c.render?c.render(r):esc(r[c.key]??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}$('#grid-footer').innerHTML=`<span>${S.pending.size?`<span class="pending-pill">저장 전 ${S.pending.size}행</span>`:''}</span><div class="flex"><select id="page-size" class="input small" aria-label="페이지당 행 수">${[25,50,100,200].map(n=>`<option ${S.pageSize===n?'selected':''}>${n}</option>`).join('')}</select><span>${S.page} / ${Math.max(1,Math.ceil(rows.length/S.pageSize))}</span>${ib('chevron','page-prev','style="transform:rotate(180deg)"','이전 페이지')}${ib('chevron','page-next','','다음 페이지')}</div>`;updateGridSelection(rows);for(const button of zoneButtons()){const cap=actionCap(button.dataset.action);if(cap&&!can(cap))button.hidden=true}for(const th of $$('#data-grid th[data-sort]')){if(th.dataset.sort==='_action')continue;th.tabIndex=0;th.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();th.click()}}}$('[data-action=page-prev]',$('#grid-footer')).disabled=S.page<=1;$('[data-action=page-next]',$('#grid-footer')).disabled=S.page>=Math.max(1,Math.ceil(rows.length/S.pageSize))}function updateGridSelection(rows=allFilteredRows()){
 const allowed=new Set(rows.map(r=>r.id));for(const id of S.selected)if(!allowed.has(id))S.selected.delete(id);
 const selected=rows.filter(r=>S.selected.has(r.id)).length,all=$('#select-page');paintGridSummary(rows);
 if(all){all.checked=rows.length>0&&selected===rows.length;all.indeterminate=selected>0&&selected<rows.length;all.setAttribute('aria-label','현재 조건의 학생 전체 선택');}
 for(const c of $$('.row-check')){c.checked=S.selected.has(c.dataset.id);c.closest('[data-row-id]')?.classList.toggle('selected',c.checked);}
 if($('#grid-selection')){$('#grid-selection').innerHTML=S.selected.size?`<div class="bulkbar"><strong>${S.selected.size}개 선택</strong>${btn('선택 해제','clear-selection','','ghost sm')}${['students','enrollments','classes','homework','accounts'].includes(S.view)?btn('상태 변경','bulk-status','','sm','edit'):''}${S.view==='parents'&&can('parent_status')?btn('선택 계정 비활성화','parents-deactivate','','sm')+btn('선택 계정 활성화','parents-activate','','sm'):''}${['students','parents'].includes(S.view)&&can(S.view==='students'?'student_delete':'parent_delete')?btn('선택 계정 삭제','accounts-delete','','danger sm'):''}${S.view==='consultations'&&can('consultation_delete')?btn('선택 상담 삭제','consult-delete-selected','','danger sm'):''}${S.view==='lessons'?btn('수업 복제','duplicate-lessons','','sm','copy'):''}</div>`:'';}
}
function zoneButtons(){return $$('#grid-zone [data-action]')}
function navigate(view){window.MiraeBack?.reset();if(view==='settings')view='detail_settings';if(!accessibleNav().some(n=>n[0]===view))return;MiraeDrafts.capture();if(S.view==='push'){const draft=MiraePushUI.captureSend?.();if(draft)MiraeDrafts.setModel('push-compose',draft)}MiraeAttendance.stash?.();MiraeDrafts.data.set('grid|'+S.user.id+'|'+S.view,{pending:[...S.pending],editing:S.editing});if(view==='messenger'&&S.view!==view)MiraeMessenger.ensureHistory();if(['attendance','attendance_book'].includes(view)&&S.view!==view)window.MiraeAttendance?.enter();S.view=view;S.q='';S.filter='';S.parentCourseFilter='';S.selected.clear();S.sort=[];S.page=1;S.editing=false;S.pending.clear();S.undo=[];$('.sidebar')?.classList.remove('open');if(view==='parents')showParents();else if(view==='accounts'){render();const node=$('#main');api('/api/accounts').then(d=>{if(node.isConnected&&S.view==='accounts'){S.accounts=d.rows;renderGridZone()}}).catch(e=>toast(e.message,true))}else render();window.scrollTo(0,0);MiraeExperience.remember()}
function columnSettings(){const cols=columnsFor();modal('보기 설정',`<div class="form-section-title">표시할 열</div><div class="col-menu">${cols.filter(c=>c.key!=='_action').map(c=>`<label class="check-label"><input type="checkbox" name="col:${c.key}" ${!(S.hidden[S.view]||[]).includes(c.key)?'checked':''}>${esc(c.label)}</label>`).join('')}</div><div class="form-section-title">행 간격</div><label class="check-label"><input type="checkbox" name="compact" ${S.compact?'checked':''}>컴팩트하게 보기</label>`,btn('적용','apply-columns','','primary'))}
function exportCSV(){const cols=columnsFor().filter(c=>c.key!=='_action'),rows=allFilteredRows();const safe=v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};const text='\uFEFF'+[cols.map(c=>safe(c.label)).join(','),...rows.map(r=>cols.map(c=>safe(c.plain?c.plain(r):r[c.key])).join(','))].join('\r\n');downloadBlob(new Blob([text],{type:'text/csv;charset=utf-8'}),`${titleFor(S.view)}_${today()}.csv`)}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function currentClass(){return S.classId||S.base.classes.find(c=>c.status==='active')?.id||S.base.classes[0]?.id||''}
async function baseOpenEditor(entity=S.view,id=null,override={}){if(entity==='classes')return classEditor(id,override);if(entity==='lessons')return lessonEditor(id,override);const student=isFamily();if(student)return;if(entity==='classes'&&S.user.role==='admin'&&!S.accounts.length){try{S.accounts=(await api('/api/accounts')).rows}catch(e){toast(e.message,true);return}}const collection=['students','classes'].includes(entity)?S.base[entity]:entity==='accounts'?S.accounts:S.data[entity]||[];const old=id?collection.find(x=>x.id===id):null;const v={...(old||{}),...override};const classField={key:'class_id',label:'강좌',type:'select',options:classOptions(),default:currentClass(),required:true,wide:true,disabled:!!old};const statusField=(opts,def)=>({key:'status',label:'상태',type:'select',options:opts.map(x=>[x,badges[x]?.[0]||x]),default:def});let fields=[];if(entity==='students')fields=[{key:'name',label:'학생명',required:true},{key:'student_no',label:'원생번호',required:true,disabled:!!old},{key:'school',label:'학교'},{key:'grade',label:'학년'},...(!old?[{...classField,key:'__class_id',label:'등록할 강좌'},{key:'__joined_on',label:'첫 수업일',type:'select',options:[],required:true}]:S.user.role==='admin'?[{key:'active',label:'학생 자료 열람 허용',type:'checkbox',default:true}]:[])];if(entity==='classes')fields=[{key:'name',label:'강좌명',required:true,wide:true},{key:'subject',label:'과목',default:'과학'},{key:'teacher_id',label:'담당 강사',type:'select',options:(S.user.role==='admin'?S.accounts.filter(a=>a.status==='active'):[S.user]).map(t=>[t.id,t.name]),default:S.user.id,required:true},{key:'start_date',label:'개강일',type:'date',default:today(),required:true},{key:'end_date',label:'종강일',type:'date',default:addDays(today(),90),required:true},statusField(['active','archived'],'active'),{key:'description',label:'강좌 안내',type:'textarea',wide:true}];if(entity==='lessons')fields=[classField,{key:'lesson_date',label:'수업일',type:'date',default:today(),required:true},{key:'title',label:'수업 제목',required:true},{key:'progress',label:'수업 진도',type:'textarea',wide:true,placeholder:'오늘 학습한 내용'},{key:'homework',label:'과제',type:'textarea',wide:true,placeholder:'과제 범위와 준비물'},{key:'online_required',label:'사진으로 온라인 제출하는 과제',type:'checkbox',wide:true},{key:'due_at',label:'제출 마감 (한국 시간)',type:'datetime-local',wide:true},{key:'video_link_text',label:'수업 영상 링크 · 한 줄에 제목 | 주소',type:'textarea',wide:true},{key:'material_link_text',label:'추가 자료 링크 · 한 줄에 제목 | 주소',type:'textarea',wide:true},{key:'notice',label:'강좌 전체 공지',type:'textarea',wide:true},{key:'published',label:'학생 · 학부모에게 공개',type:'checkbox',default:true,wide:true}];if(entity==='exams')fields=[classField,{key:'lesson_id',label:'수업 기록 연결 · 과제 검사 함께 입력',type:'select',wide:true,options:[['','연결 안 함'],...S.data.lessons.filter(l=>l.class_id===(v.class_id||currentClass())).map(l=>[l.id,l.lesson_date+' · '+l.title])]}, {key:'title',label:'시험명',required:true},{key:'exam_date',label:'시험일',type:'date',default:today(),required:true},{key:'subject',label:'과목',default:'과학'},{key:'unit',label:'단원'},{key:'max_score',label:'만점',type:'number',default:100,required:true,step:0.1,min:0.1},{key:'published',label:'성적 공개',type:'checkbox',default:true}];if(entity==='videos')fields=[classField,{key:'title',label:'영상 제목',required:true,wide:true},{key:'youtube_url',label:'YouTube 링크',type:'url',required:true,wide:true,default:old?'https://www.youtube.com/watch?v='+old.youtube_id:''},{key:'video_date',label:'수업일',type:'date',required:true,default:today()},{key:'lesson_id',label:'수업 기록 연결',type:'select',options:[['','연결 안 함'],...S.data.lessons.filter(l=>l.class_id===(v.class_id||currentClass())).map(l=>[l.id,l.lesson_date+' '+l.title])],default:''},{key:'published',label:'학생 · 학부모에게 공개',type:'checkbox',default:true}];if(entity==='accounts')fields=[{key:'name',label:'강사명',required:true},{key:'login_id',label:'로그인 아이디',required:true},{key:'password',label:old?'새 초기 비밀번호 (변경 시)':'초기 비밀번호',type:'password',required:!old},{key:'role',label:'권한',type:'select',options:[['teacher','강사'],['admin','최종관리자']],default:'teacher'},statusField(['active','inactive','departed'],'active'),{key:'can_edit_login',label:'로그인 화면 · 메인 문구 · 홍보 버튼 편집 허용',type:'checkbox',wide:true}];if(!fields.length)return;const values={...v};if(entity==='lessons')values.due_at=localTime(v.due_at);const title=(old?'수정 · ':'새로 등록 · ')+({students:'학생',classes:'반',lessons:'수업',exams:'시험',videos:'영상',accounts:'강사'})[entity];modal(title,`<form id="edit-form">${fieldsHtml(fields,values)}<div id="form-error"></div></form>`,`${old&&entity==='lessons'?btn('학생별 출석 · 코멘트','lesson-feedback',`data-id="${old.id}"`,''):''}${old&&entity==='exams'?btn('점수 입력','score-entry',`data-id="${old.id}"`,''):''}${btn('취소','close-modal')}${btn('저장','save-editor','','primary','check')}`,{wide:entity==='lessons'});if(entity==='students'&&!old)MiraeAttendanceCore.bindLessonSelect($('#edit-form'),S.base.classes,'__class_id','__joined_on');const updateDeadline=()=>{const check=$('[name=online_required]',M.node),input=$('[name=due_at]',M.node);if(check&&input){input.closest('.field').classList.toggle('hidden',!check.checked);input.required=check.checked;if(!check.checked)input.value=''}};updateDeadline();if(entity==='exams')$('[name=class_id]',M.node)?.addEventListener('change',ev=>{const select=$('[name=lesson_id]',M.node);select.innerHTML='<option value="">연결 안 함</option>'+S.data.lessons.filter(l=>l.class_id===ev.target.value).map(l=>`<option value="${l.id}">${esc(l.lesson_date+' · '+l.title)}</option>`).join('')});$('[name=online_required]',M.node)?.addEventListener('change',updateDeadline);M.save=async()=>{const form=$('#edit-form');if(!form.reportValidity())return;const payload=collect();for(const f of fields.filter(f=>f.disabled))if(old)payload[f.key]=old[f.key];if(entity==='lessons')payload.due_at=payload.online_required?toISO(payload.due_at):null;if(['videos','exams'].includes(entity)&&!payload.lesson_id)payload.lesson_id=null;if(old){payload.id=old.id;payload.version=old.version}const button=$('[data-action=save-editor]',M.node);button.disabled=true;try{await api('/api/manage/'+entity+'/bulk',{method:'POST',body:{rows:[payload]}});closeModal(true);await reload(true);toast('저장완료')}catch(e){errorBox(e.message);button.disabled=false}};$('#edit-form').addEventListener('submit',e=>{e.preventDefault();M.save()})}
async function saveGrid(){if(!S.pending.size)return;const rows=[...S.pending].map(([id,changes])=>{const original=rowsForView().find(r=>r.id===id);return{id,version:original.version,...changes}});try{await api('/api/manage/'+S.view+'/bulk',{method:'POST',body:{rows}});S.pending.clear();MiraeDrafts.data.delete('grid|'+S.user.id+'|'+S.view);S.undo=[];await reload(true);toast('저장완료')}catch(e){toast(e.message,true)}}
function studentDetail(id){const s=getStudent(id),es=S.base.enrollments.filter(e=>e.student_id===id);modal(s.name,`<div class="flex between"><div>${studentCell(s)}<div class="tagline">${badge(s.active?'active':'inactive')}<span class="badge">${esc(s.school)} ${esc(s.grade)}</span></div></div>${btn('학습 리포트','student-report',`data-id="${s.id}"`,'','reports')}</div><div class="family-assignment-strip"><span>학부모 계정 · <b>${esc((S.base.parents||[]).find(p=>p.id===s.parent_id)?.login_id||'미배정')}</b></span>${btn('학부모 정보 · 배정','parent-for-student',`data-id="${s.id}"`,'sm','students')}</div><div class="form-section-title">수강 이력</div>${es.length?simpleTable([{key:'class',label:'강좌',render:e=>`<span class="primary-text">${esc(getClass(e.class_id).name)}</span><small>${getClass(e.class_id).start_date} ~ ${getClass(e.class_id).end_date}</small>`},{key:'status',label:'상태',render:e=>badge(e.status)},{key:'snapshot',label:'당시 학교 · 학년',render:e=>esc(e.school_at_entry||'')+' '+esc(e.grade_at_entry||'')},{key:'date',label:'수강 시작',render:e=>dateText(e.joined_on,true)},{key:'action',label:'',render:e=>btn('변경','enrollment-edit',`data-id="${e.id}"`,'ghost sm','edit')}],es):empty('수강 이력이 없습니다.')}`,`${btn('다른 반에 등록','add-enrollment',`data-id="${s.id}"`,'','plus')}${btn('학생 정보 수정','edit-student',`data-id="${s.id}"`,'primary','edit')}${can('student_delete')?btn('학생 계정 삭제','account-delete',`data-kind="students" data-id="${s.id}"`,'danger'):''}`,{wide:true})}
function enrollmentEditor(id,studentId){const old=S.base.enrollments.find(e=>e.id===id);if(old?.status==='withdrawn'){toast('퇴원 처리된 수강입니다. 다시 입반하려면 다른 반에 등록을 사용하세요.',true);return}const fields=[{key:'class_id',label:'강좌',type:'select',options:classOptions(),default:currentClass(),disabled:!!old,required:true,wide:true},{key:'status',label:'수강 상태',type:'select',options:['enrolled','inactive','completed'].map(s=>[s,badges[s][0]]),default:'enrolled'},{key:'joined_on',label:'첫 수업일',type:'select',options:[],required:true},{key:'left_on',label:'수강 종료일',type:'date'}];modal(old?'수강 상태 변경':'다른 반에 등록',`<form id="enroll-form">${fieldsHtml(fields,old||{})}</form>`,btn('저장','save-editor','','primary','check'));MiraeAttendanceCore.bindLessonSelect($('#enroll-form'),S.base.classes,'class_id','joined_on',old?.joined_on);M.save=async()=>{if(!$('#enroll-form').reportValidity())return;const d=collect();d.left_on=d.left_on||null;if(old){d.id=old.id;d.version=old.version;d.class_id=old.class_id;d.student_id=old.student_id}else d.student_id=studentId;try{await api('/api/manage/enrollments/bulk',{method:'POST',body:{rows:[d]}});closeAll();await reload(true);toast('수강 상태를 저장했습니다.')}catch(e){errorBox(e.message)}}}
function bulkStatus(){const view=S.view;let options;if(view==='students'){if(!S.classId){toast('수강 상태를 변경할 반을 먼저 선택해 주세요.',true);return}options=['enrolled','inactive','completed']}else if(view==='classes')options=['active','archived'];else if(view==='accounts')options=['active','inactive','departed'];else if(view==='homework')options=['submitted','poor','passed','missing'];else return;modal('선택 항목 상태 변경',fieldsHtml([{key:'status',label:'변경할 상태',type:'select',options:options.map(s=>[s,badges[s][0]])},...(view==='students'?[{key:'left_on',label:'수강 종료일',type:'date',default:today()}]:[])]),btn(S.selected.size+'개 변경','save-editor','','primary','check'));M.save=async()=>{const d=collect();let entity=view,rows=[];if(view==='students'){entity='enrollments';rows=S.base.enrollments.filter(e=>e.class_id===S.classId&&S.selected.has(e.student_id)).map(e=>({id:e.id,version:e.version,status:d.status,left_on:['withdrawn','completed'].includes(d.status)?d.left_on||today():null}))}else if(view==='homework'){entity='submissions';rows=expectedHomework().filter(h=>S.selected.has(h.id)&&h.submission).map(h=>({id:h.submission.id,version:h.submission.version,status:d.status}));if(rows.length<S.selected.size){errorBox('아직 사진을 제출하지 않은 학생은 제출 내역이 없어 일괄 상태를 바꿀 수 없습니다. 제출된 항목만 선택해 주세요.');return}}else rows=rowsForView().filter(r=>S.selected.has(r.id)).map(r=>({id:r.id,version:r.version,status:d.status}));try{await saveChunks(entity,rows);closeModal(true);S.selected.clear();await reload(true);toast('상태를 변경했습니다.')}catch(e){errorBox(e.message)}}}
async function saveChunks(entity,rows){if(!rows.length)throw new Error('저장할 변경 내용이 없습니다.');if(rows.length>200)throw new Error('한 번에 200행 이하로 선택해 주세요.');return api('/api/manage/'+entity+'/bulk',{method:'POST',body:{rows}})}

// Flexible, quote-aware spreadsheet import; imported data are never evaluated as formulas.
function parseDelimited(text,delimiter){text=String(text).replace(/^\uFEFF/,'').replace(/\r\n/g,'\n');delimiter=delimiter||(text.includes('\t')?'\t':',');let out=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else if(quoted||!cell)quoted=!quoted;else cell+=c}else if(c===delimiter&&!quoted){row.push(cell);cell=''}else if(c==='\n'&&!quoted){row.push(cell);out.push(row);row=[];cell=''}else cell+=c}row.push(cell);out.push(row);return out.filter(r=>r.some(x=>x.trim()!==''))}
const importDefinitions={students:[['name','학생명','학생명|이름|학생|성명|원생명|name'],['student_no','원생번호','원생번호|학생번호|고유번호|student_no'],['school','학교','학교|학교명'],['grade','학년','학년'],['__class_name','등록할 반','반명|강좌|반']],classes:[['name','반명','반명|강좌|반'],['subject','과목','과목'],['start_date','개강일','개강일|시작일|개강'],['end_date','종강일','종강일|종료일|종강'],['__teacher','담임','강사|담당|담당강사|담임'],['__assistant','부담임','부담임|보조강사'],['description','반 안내','안내|설명']],exams:[['title','시험명','시험명|시험|제목'],['exam_date','시험일','시험일|날짜|일자'],['max_score','만점','만점|총점'],['subject','과목','과목'],['unit','단원','단원|영역'],['__class_name','강좌','반명|강좌|반']],videos:[['title','영상 제목','영상명|제목|영상제목'],['youtube_url','YouTube 링크','링크|url|유튜브|영상주소'],['video_date','수업일','날짜|수업일|일자'],['__class_name','강좌','반명|강좌|반']]};
function importDate(v){v=String(v||'').trim();if(/^\d{5}$/.test(v))return new Date(Date.UTC(1899,11,30)+Number(v)*86400000).toISOString().slice(0,10);const m=v.match(/^(\d{2,4})[.\-/년 ]+\s*(\d{1,2})[.\-/월 ]+\s*(\d{1,2})/);if(m)return(m[1].length===2?'20':'')+m[1]+'-'+m[2].padStart(2,'0')+'-'+m[3].padStart(2,'0');return v}
function openImport(entity=S.view){if(entity==='students')return registration();const defs=importDefinitions[entity];if(!defs)return;let raw=[],hasHeader=true,mapping=[];modal(titleFor(entity)+' 일괄 입력',`<div class="import-toolbar"><label class="btn">${icon('file')}CSV · TSV 파일<input type="file" id="import-file" accept=".csv,.tsv,.txt" hidden></label><label class="check-label"><input type="checkbox" id="import-header" checked>첫 줄은 제목</label>${entity!=='classes'?`<select id="import-class">${classOptions().map(o=>`<option value="${o[0]}" ${o[0]===currentClass()?'selected':''}>${esc(o[1])}</option>`).join('')}</select>`:''}</div><textarea id="paste-source" class="paste-box" rows="5" placeholder="엑셀에서 여러 행과 열을 복사해 여기에 붙여넣으세요. 열 순서는 자유롭게 연결할 수 있습니다."></textarea><div class="flex between" style="margin:12px 0"><span class="muted" id="import-count">최대 200행씩 저장</span>${btn('붙여넣은 내용 확인','parse-import','','','grid')}</div><div id="import-preview"></div>`,btn('취소','close-modal')+btn('검사 후 저장','save-import','','primary','check'),{wide:true});const node=M.node;const parse=()=>{raw=parseDelimited($('#paste-source',node).value);hasHeader=$('#import-header',node).checked;if(!raw.length){$('#import-preview',node).innerHTML=empty('붙여넣은 내용이 없습니다.');return}const count=Math.max(...raw.map(r=>r.length));mapping=Array.from({length:count},(_,i)=>{const h=hasHeader?(raw[0][i]||'').replace(/\s/g,'').toLowerCase():'';return defs.find(d=>new RegExp('^(?:'+d[2]+')$','i').test(h))?.[0]||(!hasHeader?defs[i]?.[0]||'':'')});preview()};const preview=()=>{let rows=hasHeader?raw.slice(1):raw;$('#import-count',node).textContent=rows.length+'행 · '+mapping.length+'열';$('#import-preview',node).innerHTML=`<div class="table-scroll import-matrix"><table class="data-table"><thead><tr><th>#</th>${mapping.map((m,i)=>`<th><small>${esc(hasHeader?raw[0][i]||'빈 열':String.fromCharCode(65+i))}</small><select data-map="${i}"><option value="">가져오지 않음</option>${defs.map(d=>`<option value="${d[0]}" ${m===d[0]?'selected':''}>${d[1]}</option>`).join('')}</select></th>`).join('')}</tr></thead><tbody>${rows.slice(0,200).map((r,n)=>`<tr><td>${n+1}</td>${mapping.map((m,i)=>`<td><input data-import-r="${n+(hasHeader?1:0)}" data-import-c="${i}" value="${esc(r[i]||'')}" aria-label="${n+1}행 ${i+1}열"></td>`).join('')}</tr>`).join('')}</tbody></table></div>`;$$('[data-map]',node).forEach(x=>x.onchange=()=>mapping[+x.dataset.map]=x.value);$$('[data-import-r]',node).forEach(x=>x.oninput=()=>raw[+x.dataset.importR][+x.dataset.importC]=x.value)};node.querySelector('[data-action=parse-import]').onclick=parse;$('#import-header',node).onchange=parse;$('#paste-source',node).addEventListener('paste',()=>setTimeout(parse,0));$('#import-file',node).onchange=async e=>{const f=e.target.files[0];if(!f)return;const b=await f.arrayBuffer();let text=new TextDecoder('utf-8').decode(b);if(text.includes('\ufffd'))text=new TextDecoder('euc-kr').decode(b);$('#paste-source',node).value=text;parse()};node.querySelector('[data-action=save-import]').onclick=async()=>{if(!raw.length)parse();const source=hasHeader?raw.slice(1):raw;if(!source.length)return errorBox('붙여넣은 데이터를 확인해 주세요.');if(source.length>200)return errorBox('200행 이하로 나누어 저장해 주세요.');const used=mapping.filter(Boolean);if(new Set(used).size!==used.length)return errorBox('같은 항목에 두 개의 열을 연결할 수 없습니다.');let rows=[];try{for(let n=0;n<source.length;n++){const d={};mapping.forEach((k,i)=>{if(k)d[k]=(source[n][i]||'').trim()});const cid=$('#import-class',node)?.value;const cls=d.__class_name?S.base.classes.filter(c=>c.name===d.__class_name):null;if(cls&&cls.length!==1)throw Error(`${n+1}행: 반명이 일치하는 반을 하나로 찾지 못했습니다.`);const rowClass=cls?.[0]?.id||cid;delete d.__class_name;if(entity==='students'){d.__class_id=rowClass;d.__joined_on=today();if(!d.student_no||!d.name)throw Error(`${n+1}행: 학생명 · 원생번호를 확인해 주세요.`)}if(entity==='classes'){const teacher=d.__teacher?S.base.teachers.filter(t=>t.name===d.__teacher||t.login_id===d.__teacher):[];if(d.__teacher&&teacher.length!==1)throw Error(`${n+1}행: 담당 강사를 찾을 수 없거나 이름이 중복되었습니다.`);if(S.user.role==='admin'&&!teacher.length)throw Error(`${n+1}행: 관리자 등록에는 담임을 입력해야 합니다.`);if(S.user.role==='teacher'&&teacher.length&&teacher[0].id!==S.user.id)throw Error(`${n+1}행: 강사가 추가하는 반의 담임은 본인입니다.`);d.teacher_id=S.user.role==='teacher'?S.user.id:teacher[0].id;const assistant=d.__assistant?S.base.teachers.filter(t=>t.status==='active'&&(t.name===d.__assistant||t.login_id===d.__assistant)):[];if(d.__assistant&&assistant.length!==1)throw Error(`${n+1}행: 부담임을 한 명으로 찾을 수 없습니다.`);d.assistant_teacher_id=assistant[0]?.id||null;delete d.__teacher;delete d.__assistant;d.start_date=importDate(d.start_date);d.end_date=importDate(d.end_date);d.status='active'}if(entity==='exams'){d.class_id=rowClass;d.exam_date=importDate(d.exam_date||today());d.max_score=d.max_score===''||d.max_score===undefined?100:Number(d.max_score);d.published=true}if(entity==='videos'){d.class_id=rowClass;d.video_date=importDate(d.video_date||today());d.published=true}rows.push(d)}await saveChunks(entity,rows);closeModal(true);await reload(true);toast(rows.length+'행을 저장했습니다.')}catch(e){errorBox(e.message)}}}

