 const l=S.data.lessons.find(x=>x.id===id);if(!l)return;const family=isFamily(),f=S.data.feedback.find(x=>x.lesson_id===id&&x.student_id===childID()),h=expectedHomework().find(x=>x.lesson_id===id&&x.student_id===childID());
